type SlideKey='cover'|'alps'|'ownership'|'aws'|'company'|'problem'|'risk'|'case'|'map'|'calc'|'compare'|'pricing'|'path'|'now'|'reading';
const ORDER:SlideKey[]=["cover", "alps", "ownership", "aws", "company", "problem", "risk", "case", "map", "calc", "compare", "pricing", "path", "now", "reading"];
const META:Record<SlideKey,{title:string;note:string;talk:string;hint?:string;cls?:string}>={
cover:{title:"Introduction",cls:"cover",note:"Tagline and three-beat value proposition agreed in the ALPS–Contiinex meeting of 9 Sep 2026: agentic AI inside the client environment, denials prevented upstream, operating margin multiplied. The 3 to 4x multiple is illustrative on the calculator defaults (1.5% baseline operating margin; cost to collect 3.5%, denial write-offs 2.7% and patient balance write-offs 1.3% of net patient revenue, each reduced 40%), which move operating margin from 1.5% to 4.5%, about 3x; see the calculator slide. Platform overview adapted from source slides 9, 11 and 16.",talk:"You own the process. We move the margin. That is the whole idea. You keep your revenue cycle, your data and your team exactly where they are. Contiinex brings agentic AI inside your walls, prevents denials before they happen, and moves the one number your board watches: operating margin. For a median hospital, that is three to four times today’s margin."},
alps:{title:"Vetted by ALPS",cls:"alps-slide",note:"ALPS description (Enterprise Marketplace, Fortune 500 clients, 225+ ALPS Advisors) supplied by ALPS on 9 Sep 2026 and consistent with acadialps.com positioning. The on-premise agentic capability is the selection reason ALPS gave in the 9 Sep 2026 meeting. ALPS logo, hero blue (#2da4f2), navy (#103758) and the mountain image come from acadialps.com, fetched 9 Sep 2026; confirm ALPS brand usage before external use.",talk:"I did not bring this to you lightly. ALPS is an Enterprise Marketplace with a track record of bringing best-of-class solutions to Fortune 500 companies through its network of more than two hundred twenty-five ALPS Advisors. We vetted Contiinex and chose it for one reason above all: it is agentic AI that runs on premise, inside your environment."},
ownership:{title:"Ownership",note:"“Only on-prem” is positioning supplied in the company brief, not independently verified market exclusivity. The source deck describes deployment in the client’s private cloud, which is distinct from physical on-premises infrastructure. Validate the intended deployment definition before external use. PHI handling statement: source slide 16.",talk:"You will want to know where your data goes. It stays with you. Contiinex runs inside your private environment. PHI stays on your infrastructure, and Contiinex does not store it on its own systems. Your data, your workflows, your oversight."},
aws:{title:"AWS partner",cls:"partner-slide",note:"AWS partnership and AWS credits: source deck, slide 15. The procurement line restates the source deck; confirm the current AWS Partner tier and whether an AWS Marketplace listing exists before external use. Private-cloud deployment and the PHI handling statement come from source slides 15 and 16.",talk:"Procurement is straightforward. Contiinex is an AWS Partner, so you can bring it in through the AWS ecosystem you already use, deploy it in your private cloud, and apply AWS credits to the implementation."},
company:{title:"Company",cls:"credibility",note:"The 1,800+ white-label practice installation claim comes from the supplied company brief (figure updated from 1,000+ on 10 Sep 2026 at the company’s direction) and does not appear in the source deck.",talk:"This is not a pilot product. Contiinex already runs white-label installations across more than eighteen hundred practices. The platform is proven at volume. What is new is bringing it to hospital systems like yours, through ALPS."},
problem:{title:"The margin problem",note:"Median hospital operating margin of 1.7% and revenue cycle management consuming 7–10% of net revenue: source slide 2 (Fiercehealthcare). The bar uses 10%, the figure agreed in the 9 Sep meeting; “six times” compares 10% with 1.7%. Denial rate of 12–13% growing about 20% year over year, cost to collect rising 25% year over year, and about 70% of denials written off: source slide 4 (Business Wire; Mordor Intelligence; National Library of Medicine; Contiinex GTM research). The closing line paraphrases source slide 4.",talk:"Here is the situation in one picture. Of every hundred dollars of net patient revenue, about ten go to running the revenue cycle, and the median hospital keeps one dollar seventy. The revenue cycle costs roughly six times what you keep. Three reasons keep that number stuck. Twelve to thirteen percent of claims are denied, and the rate grows about twenty percent a year. The cost to collect rises about twenty-five percent a year, even with offshoring. And seventy percent of denials are never worked at all. Fix one of those in isolation and the other two absorb the loss."},
risk:{title:"Compounding risk",hint:"Builds one stage per page turn",note:"Conceptual animation, not a quantitative forecast. The rising curve represents accumulating process burden and revenue exposure, not measured costs or probabilities. Stage statistics: 26.6% of denials traced to incorrect demographic or intake data (source slide 5, industry claims-denial analysis 2025); 13 hours per physician per week on prior authorization (source slide 8, HPI State of RCM 2026); 12–13% denial rate growing about 20% a year and cost to collect up 25% a year (source slide 4); 70% of denials written off and under 0.2% reaching external appeal (source slide 7; Business Wire, National Library of Medicine, KFF).",talk:"Follow one claim. A small intake error at registration becomes a missing authorization, then a denial, then rework, and finally a write-off. About a quarter of denials start with intake data. Physicians lose thirteen hours a week to prior authorization. Most denials are never worked, and fewer than two in a thousand are ever appealed. No single stage is the problem. The problem is that cost compounds at every step while your cash slows down."},
case:{title:"Case study",note:"Industry case study, not a Contiinex engagement. Figures and the quotation come from Becker’s Hospital Review, “Cleveland Clinic’s $15B revenue cycle and the ‘unsustainable’ problem it hopes to solve” by Alan Condon, June 25, 2026, reporting 2025 results: more than $15 billion in U.S. net patient revenue, more than 3,800 revenue cycle FTEs, a 2.92% cost to collect, a 15% incoming denial rate covering initial and subsequent denials, 92% of denials overturned, net controllable loss under 2%, roughly 200 RPA bots, and about 40% of revenue cycle operations outsourced. The bar splits claims as roughly 85% paid without denial, 13 points denied then overturned, and under 2% lost; it is derived from those figures, not published as such. Cleveland Clinic is not a Contiinex client; the example illustrates the industry problem and direction. Article: https://www.beckershospitalreview.com/finance/cleveland-clinics-15b-revenue-cycle-and-the-unsustainable-problem-it-hopes-to-solve/ (published June 25, 2026). Photo: “Cleveland Clinic entrance” by Mutaz Albar, CC BY 3.0, via Wikimedia Commons (commons.wikimedia.org/wiki/File:Cleveland_Clinic_entrance_(111095553).jpg), resized for the deck.",talk:"Scale and headcount do not solve this. Cleveland Clinic runs a fifteen-billion-dollar revenue cycle with more than thirty-eight hundred staff and about two hundred automation bots, and still sees fifteen percent of claims denied. They overturn ninety-two percent, but only after rework, and their CFO calls it unsustainable. Their answer is the right one: prevent denials upstream and automate with a person in the loop. Contiinex is how a system your size does that now, without building it yourself. The full Becker’s Hospital Review article is linked on this slide."},
map:{title:"Intervention",hint:"Builds one stage per page turn",note:"Interventions and workflow names derive from source slides 9 and 10. The ring is conceptual: each stage seals as Contiinex acts, showing where it intervenes, not a measured reduction. Stages 1 and 2 are upstream prevention; stages 3 to 5 are downstream recovery. Product names (AgentNex, AuditNex) are intentionally omitted, per the 9 Sep meeting, in favour of upstream and downstream.",talk:"Now the same five stages with Contiinex in place, sealed one by one around your revenue cycle. Upstream, agents validate intake, verify eligibility and benefits, and secure prior authorization, so the denial never happens. Downstream, they decode every denial, choose the next action, correct and resubmit, appeal and follow up with payers by voice, and audit underpayments and zero-balance accounts. Upstream prevents. Downstream recovers. Every leak is stopped where it starts."},
calc:{title:"Your numbers",hint:"Interactive: enter your revenue",note:"Illustrative model, not a forecast or a guarantee. Value model supplied by Contiinex on 10 Sep 2026: three lines, each stated as a share of net patient revenue (NPR), with one reduction applied to each. Defaults: cost to collect 3.5% of NPR, denial write-offs 2.7%, patient balance write-offs 1.3%, a 40% reduction on each line (company-reported 40%+ cost reduction and about 40%+ denial revenue recovery, source slide 11), and a 1.5% baseline operating margin. On a $1B NPR that gives $14M, $10.8M and $5.2M a year, $30M in total, 300 basis points, and operating margin from 1.5% to 4.5%; the supplied model shows 4.4%, a rounding difference. Cost-to-collect savings reduce expense; write-off reductions are treated as recovered revenue; all three are assumed to flow fully to operating margin. The margin-problem slide cites the 1.7% industry median from source slide 2; the calculator default of 1.5% follows the supplied model. Every input is adjustable and is replaced by the client’s own data in the diagnostic.",talk:"This is what it means for you. Start from your net patient revenue. Three lines move. Cost to collect, about three and a half percent of revenue today, falls by forty percent. Denial write-offs, about two point seven percent, fall by forty percent. Patient balance write-offs, about one point three percent, fall by forty percent. For a one-billion-dollar system that is thirty million dollars a year, three hundred basis points, and operating margin from one and a half percent to four and a half. Every assumption here is adjustable, and the diagnostic replaces all of them with your own claims data."},
compare:{title:"How we differ",note:"Comparison derived from source slides 13 and 14 and the 9 Sep meeting. Alternatives are described as categories, not named vendors; the contingency-fee column reflects ALPS’s description of the incumbent alternative. Attrition near 35% and loaded cost of $60–70K per agent per year: source slides 6 and 14. The licensing statement matches the pricing slide: an annual platform license plus usage-based consumption, with no share of recoveries. Confirm rate cards before external use. Integrations: source slide 15.",talk:"You have seen the alternatives. In-house and offshore teams are limited by attrition and months of ramp. Point automation handles one step and still needs people to act on what it finds. Contingency vendors work denials after the fact, with their own people, on their own infrastructure, for a share of every dollar. Contiinex prevents and recovers, with agents instead of headcount, inside your own cloud, under a license, so what is recovered stays on your books."},
pricing:{title:"Pricing",hint:"Interactive: numbers follow the revenue on Your numbers",note:"Pricing structure (Deploy, Subscribe, Consume) supplied by ALPS on 9 Sep 2026. The consumption calculator mirrors “Financial Model_Contiinex.xlsx”, sheet “12 months”: transactions per agent per year = (60 ÷ handle time) × 7 hours × 20 days × 12 months; team capacity = that × agents; manual cost per transaction = loaded cost ÷ productivity; agentic transactions = capacity × share impacted; Contiinex price per transaction = manual cost × 40%; infrastructure = $0.01 per transaction; savings = manual equivalent − (agentic + infrastructure). The workbook fixes 500 addressable agents without a revenue; this deck scales staffing from the revenue entered on the Your numbers slide at 500 agents per $1B of net patient revenue (adjustable in Settings; for reference, Cleveland Clinic runs about 250 revenue cycle FTEs in total per $1B), which reproduces the workbook at the $1B default: $20.0M manual, $8.03M with Contiinex, $11.97M saved. Two workbook remarks disagree with their formulas: “at 40% cost save” next to a price set at 40% of manual cost (a 60% saving per transaction), and “$0.05 per transaction” next to an infrastructure formula using $0.01; the calculator follows the formulas. The ~$1,000 per $1M license benchmark and the implementation fee are not in the workbook. Confirm rate cards, both discrepancies and the consumption unit prices before external use.",talk:"Pricing is simple and predictable, and it is aligned to outcomes. Three parts. Deploy: a one-time implementation covering EHR and practice management integration and secure private-cloud setup. Subscribe: an annual platform license scaled to your revenue, about a thousand dollars per million as a benchmark. Consume: you pay only for what you use, per transaction or case for back-office AI and per minute for voice AI. The numbers below follow the revenue you entered a moment ago. For a billion-dollar system that is about five hundred revenue cycle agents in scope; Contiinex takes on eighty percent of their transactions at forty percent of your cost per transaction, so twenty million dollars of manual work gets done for eight, twelve million a year comes back to you, and four hundred people’s worth of capacity is freed for the work that needs a person. Add your license and implementation and you can see the net and the payback."},
path:{title:"Path to value",note:"Source slide 16 specifies a 2–4 week diagnostic with no integration required to start and a 60–90 day pilot. Slide 14 separately describes 4 weeks to pilot readiness; this presentation uses the more detailed phased timeline. Source: Contiinex–ALPS RCM Sales PitchDeck, 8 Sep, plus the 9 Sep ALPS–Contiinex meeting and user-supplied company positioning.",talk:"The first step is small. A two to four week diagnostic on your own claims data, with no integration required to start. Then a sixty to ninety day pilot on one or two service lines inside your private cloud, measured against your own baseline. Then scale across your full claims volume. You own the process. We move the margin."},
now:{title:"Appendix: Why now",cls:"appendix",note:"CMS Interoperability and Prior Authorization final rule CMS-0057-F: impacted payers must implement FHIR-based prior authorization APIs by January 1, 2027 (source slide 3). Prior authorization burden of about 13 hours per physician per week, with roughly 30% denied: source slide 8 (HPI, State of RCM 2026). The two stances, compliance readiness and compounding value as payer APIs open, come from the 9 Sep meeting. “Built for this” is Contiinex’s positioning; confirm the FHIR capability statement before external use.",talk:"If the question of timing comes up, here is the clock. From January 1, 2027, CMS-regulated payers must run electronic, FHIR-based prior authorization APIs. The payers will be ready. Providers still handling authorization by hand will not be able to keep pace with them. Contiinex already runs prior authorization as an automated, electronic workflow, so the mandate becomes a tailwind rather than a project. And every payer API that opens makes the same platform faster and wider, so what you buy now is worth more each year the mandate phases in."},
reading:{title:"Further reading",cls:"appendix",note:"Further reading, linked for reference. EY: “How AI can transform the revenue cycle in healthcare” by Jon Rasul, EY Health Consulting revenue cycle leader, ey.com, published 27 Mar 2026 (fetched 10 Sep 2026). Figures on the slide come from that article: nearly half of provider organizations report 10% or more of claims denied; the share with 10%+ denial rates was 30% in 2022, 38% in 2024 and 41% in 2025; 54% say claim errors are increasing; 59% plan to invest in claims processing or denial reduction technology within six months; 90% of CEOs expect AI to have a significant or transformative impact on business models. Becker’s Hospital Review: “Cleveland Clinic’s $15B revenue cycle and the ‘unsustainable’ problem it hopes to solve” by Alan Condon, 25 Jun 2026; details as on the case study slide. Both are third-party publications and neither describes a Contiinex engagement.",talk:"If you want to go deeper, two pieces are worth your time. EY’s revenue cycle leader lays out why denial rates keep climbing and where AI changes the economics of the revenue cycle. And Becker’s Hospital Review’s look at Cleveland Clinic shows a fifteen-billion-dollar revenue cycle reaching the same conclusion we have: prevent denials upstream, and automate with a person in the loop. Both links open from this slide."}
};
const titles=ORDER.map(k=>META[k].title);
const LAST=4;
const LAST_SLIDE=titles.length-1;
const isJourney=(s:number)=>ORDER[s]==='risk'||ORDER[s]==='map';
const RED='M30 207 C140 205 210 190 240 180 S390 156 450 136 S610 91 660 77 S815 30 870 18';
const RISK_Y=[207,180,136,77,18];
const RING_R=165,RING_CX=450,RING_CY=235;
const nodePos=(i:number):[number,number]=>{const a=(-90+72*i)*Math.PI/180;return [RING_CX+RING_R*Math.cos(a),RING_CY+RING_R*Math.sin(a)]};
const arcPath=(i:number)=>{const [x1,y1]=nodePos(i),[x2,y2]=nodePos((i+1)%5);return `M${x1.toFixed(1)} ${y1.toFixed(1)} A${RING_R} ${RING_R} 0 0 1 ${x2.toFixed(1)} ${y2.toFixed(1)}`};
const RING_LABELS:{x:number;y:number;a:'start'|'middle'|'end'}[]=[{x:450,y:26,a:'middle'},{x:640,y:180,a:'start'},{x:547,y:412,a:'middle'},{x:353,y:412,a:'middle'},{x:260,y:180,a:'end'}];
const money=(v:number)=>{const a=Math.abs(v);const s=a>=1e9?`$${a>=1e10?(a/1e9).toFixed(0):(a/1e9).toFixed(1).replace(/\.0$/,'')}B`:a>=1e7?`$${Math.round(a/1e6)}M`:a>=1e6?`$${(a/1e6).toFixed(1)}M`:`$${Math.round(a/1e3)}K`;return (v<0?'-':'')+s};
const REV_MIN=1e8,REV_SPAN=200;
const revFromSlider=(v:number)=>{const r=REV_MIN*Math.pow(REV_SPAN,v/1000);return r>=1e9?Math.round(r/5e7)*5e7:Math.round(r/1e7)*1e7};
const sliderFromRev=(r:number)=>Math.round(Math.log(Math.min(Math.max(r,REV_MIN),REV_MIN*REV_SPAN)/REV_MIN)/Math.log(REV_SPAN)*1000);
