{sk==='company'&&<><h2>Built for your ecosystem.<br/><em>Deployed at scale.</em></h2><div className="proof"><div className="scale"><strong>1,800<span>+</span></strong><p>practices with white-label installations¹</p></div><div className="signal"><i/>Your infrastructure. Your control.</div></div></>}
{sk==='compare'&&<><h2>Not another vendor<br/><em>working your denials.</em></h2><div className="compare-wrap"><table className="compare"><thead><tr><th/><th>In-house or offshore staff</th><th>Point automation</th><th>Contingency-fee vendors</th><th className="us">Contiinex</th></tr></thead><tbody>{COMPARE.map(r=><tr key={r[0]}><th>{r[0]}</th><td>{r[1]}</td><td>{r[2]}</td><td>{r[3]}</td><td className="us">{r[4]}</td></tr>)}</tbody></table></div><div className="integration"><span>PRE-INTEGRATED</span><p>Connected to your EHR, practice management, billing, clearinghouse and payer systems.</p></div></>}
